import argparse
import sqlite3
import sys
from datetime import datetime

def generate_html_report(db_path, out_path, min_price=None):
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        query = "SELECT name, category, price FROM items"
        if min_price is not None:
            query += f" WHERE price >= {min_price}"
        cursor.execute(query)
        rows = cursor.fetchall()
        conn.close()

        html = """<html>
<head>
    <title>Inventory Report</title>
    <style>
        table {
            border-collapse: collapse;
            width: 100%;
        }
        th, td {
            border: 1px solid #dddddd;
            text-align: left;
            padding: 8px;
        }
        th {
            background-color: #f2f2f2;
        }
    </style>
</head>
<body>
    <h1>Inventory Report</h1>
    <table>
        <thead>
            <tr>
                <th>Name</th>
                <th>Category</th>
                <th>Price</th>
            </tr>
        </thead>
        <tbody>
"""
        for name, category, price in rows:
            html += f"            <tr><td>{name}</td><td>{category}</td><td>${price:.2f}</td></tr>\n"

        html += """
        </tbody>
    </table>
</body>
</html>
"""
        with open(out_path, 'w') as f:
            f.write(html)
        return len(rows)
    except Exception as e:
        raise e

def log_entry(level, message):
    timestamp = datetime.now().isoformat()
    log_entry = f"{timestamp} {level} {message}\n"
    return log_entry

def main():
    parser = argparse.ArgumentParser(description='Generate an inventory report from a SQLite database.')
    parser.add_argument('--db', required=True, help='Path to the SQLite database file')
    parser.add_argument('--out', required=True, help='Path to the output HTML file')
    parser.add_argument('--log', help='Path to the log file')
    parser.add_argument('--min-price', type=float, help='Minimum price threshold for filtering items')

    args = parser.parse_args()

    try:
        rows_count = generate_html_report(args.db, args.out, args.min_price)
        if args.log:
            log_message = log_entry("INFO", f"Successfully generated report with {rows_count} items")
            with open(args.log, 'a') as f:
                f.write(log_message)
    except Exception as e:
        error_message = log_entry("ERROR", f"Failed to generate report: {str(e)}")
        if args.log:
            with open(args.log, 'a') as f:
                f.write(error_message)
        sys.exit(1)

    sys.exit(0)

if __name__ == "__main__":
    main()

import argparse
import sqlite3
import sys
from datetime import datetime

def parse_arguments():
    parser = argparse.ArgumentParser()
    parser.add_argument('--db', required=True, help='Path to the SQLite database file')
    parser.add_argument('--out', required=True, help='Path to the output HTML file')
    parser.add_argument('--log', required=True, help='Path to the log file')
    parser.add_argument('--filter', required=True, help='Path to the SQL filter file')
    return parser.parse_args()

def read_filter_file(filter_path):
    try:
        with open(filter_path, 'r') as file:
            return file.read().strip()
    except IOError as e:
        raise RuntimeError(f"Failed to read filter file: {e}")

def execute_query(db_path, filter_condition):
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute("SELECT name, category, price FROM items WHERE " + filter_condition)
        rows = cursor.fetchall()
        conn.close()
        return rows
    except sqlite3.Error as e:
        raise RuntimeError(f"Failed to read database: {e}")

def generate_html(rows, out_path):
    try:
        with open(out_path, 'w') as file:
            file.write("<!DOCTYPE html>\n<html>\n<head>\n    <title>Inventory Report</title>\n</head>\n<body>\n    <h1>Inventory Report</h1>\n    <table>\n")
            for row in rows:
                name, category, price = row
                file.write(f"        <tr>\n            <td>{name}</td>\n            <td>{category}</td>\n            <td>{price:.2f}</td>\n        </tr>\n")
            file.write("    </table>\n</body>\n</html>")
    except IOError as e:
        raise RuntimeError(f"Failed to write HTML file: {e}")

def log_message(log_path, level, message):
    try:
        with open(log_path, 'a') as file:
            timestamp = datetime.now().isoformat()
            file.write(f"{timestamp} {level} {message}\n")
    except IOError as e:
        raise RuntimeError(f"Failed to write log file: {e}")

def main():
    args = parse_arguments()
    try:
        filter_condition = read_filter_file(args.filter)
        rows = execute_query(args.db, filter_condition)
        generate_html(rows, args.out)
        log_message(args.log, "INFO", f"Successfully wrote {len(rows)} rows to HTML file")
    except RuntimeError as e:
        log_message(args.log, "ERROR", str(e))
        sys.exit(1)

if __name__ == "__main__":
    main()
